import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

function runCommand(command: string): { stdout: string, stderr: string } {
  try {
    const output = execSync(command, { cwd: process.cwd(), encoding: 'utf8' });
    return { stdout: output, stderr: '' };
  } catch (error) {
    return { stdout: '', stderr: error.stderr.toString() };
  }
}

function checkExample(example: string): boolean {
  const [command, expectedOutput] = example.split('```').map(s => s.trim());
  const { stdout, stderr } = runCommand(command);

  const expectedLines = expectedOutput.split('\n').map(s => s.trim()).filter(s => s !== '' && !s.startsWith('$ '));
  const actualLines = stdout.split('\n').map(s => s.trim()).filter(s => s !== '' && !s.startsWith('$ '));

  if (expectedLines.length !== actualLines.length) {
    console.error(`Example differs: Expected ${expectedLines.length} lines, got ${actualLines.length} lines`);
    return false;
  }

  for (let i = 0; i < expectedLines.length; i++) {
    if (expectedLines[i] !== actualLines[i]) {
      console.error(`Example differs at line ${i + 1}: Expected '${expectedLines[i]}', got '${actualLines[i]}'`);
      return false;
    }
  }

  return true;
}

function checkDocs(filePath: string): boolean {
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const examples = fileContent.match(/\$ ledgerline [^`]*?```/g);

  if (!examples) {
    console.error('No examples found in the file.');
    return false;
  }

  return examples.every(checkExample);
}

const filePath = process.argv[2] || 'README.md';
const success = checkDocs(filePath);

if (success) {
  console.log('All examples match the expected output.');
  process.exit(0);
} else {
  console.error('Some examples do not match the expected output.');
  process.exit(1);
}
